//! The WGSL shell (a compute shader): the scalar and array storage buffers the uniforms live in,
//! the texture bindings, the `scalar_*` readers, then `ocio_transform` around the op bodies of
//! `gpu/ops.rs` (written once for every language, ROADMAP G6). The compute entry points are in
//! `gpu/runtime.rs`. Nothing here is colour maths.

use super::*;
use crate::gpu_shader_utils::ShaderText;

impl GpuProcessor {
    // =========================================================================
    // WGSL (WebGPU Shading Language) Generation
    // =========================================================================

    /// Generates the WGSL PRELUDE: uniform decls, LUT texture bindings, helpers, and
    /// `fn ocio_transform(vec4) -> vec4` — everything up to but NOT including a compute-shell
    /// entry point.
    ///
    /// Split out of [`Self::generate_wgsl`] for PLAN9.md O0/C6: `gpu/runtime.rs`'s caching
    /// executors need this piece alone, to concatenate their OWN shell (D1 host-buffer or the
    /// zero-copy texture-IO one) onto it directly — no `.find()` search for a marker string, no
    /// re-emitting the colour maths per shell variant.
    pub(super) fn generate_wgsl_prelude(
        &self,
        uniform_bindings: &[Option<OpUniforms>],
        uniforms: &[GpuUniform],
    ) -> String {
        let mut st = ShaderText::new();

        st.line("// WGSL Compute Shader Generated by vfx-ocio");
        st.new_line();

        // Uniform struct
        self.emit_uniform_decls_wgsl(&mut st, uniforms);

        // LUT texture bindings
        self.emit_texture_bindings_wgsl(&mut st);

        // Helper functions
        for line in ops::helpers(self, &dialect::WGSL, uniform_bindings) {
            st.linef(line);
        }

        // Color transform function
        st.line("fn ocio_transform(color_in: vec4<f32>) -> vec4<f32> {");
        st.indent();
        st.line("var color = color_in;");
        st.new_line();

        for line in ops::body(self, &dialect::WGSL, uniform_bindings) {
            st.linef(line);
        }

        st.line("return color;");
        st.dedent();
        st.line("}");
        st.new_line();

        st.into_code()
    }

    /// PUBLIC host API (task: "the WGSL prelude ... is public"): this processor's WGSL prelude —
    /// uniform decls, LUT texture bindings, helpers, and `fn ocio_transform(vec4<f32>) -> vec4<f32>`
    /// — with NO compute-shell entry point appended.
    ///
    /// Any host that wants to run this processor's colour transform on its OWN `wgpu::Device`, with
    /// its OWN entry point and its OWN `@group(0)` input/output resources, appends its shell text
    /// directly to this string — no marker string, no `.find("@group(0)")` splice (the bug vfx-view's
    /// `OcioGpuPass::wrap_ocio_wgsl` has today: it cuts the FULL `generate_shader(Wgsl)` output at the
    /// first `"@group(0)"` occurrence, which is fragile and duplicates what this method now does
    /// directly). [`super::runtime::CompiledOcio::compile`] — the shared-device runtime — calls this
    /// SAME method; there is exactly one WGSL-prelude emitter in this crate.
    ///
    /// The host's shell must:
    /// - declare `@group(0)` however it needs (its own input/output resources — this prelude never
    ///   touches group 0);
    /// - call [`super::WGSL_TRANSFORM_FUNCTION`] (`"ocio_transform"`) with a `vec4<f32>` and use its
    ///   `vec4<f32>` result;
    /// - if [`GpuShaderCode::binding_contract`] (call [`Self::generate_shader`] once to get the
    ///   [`GpuShaderCode`], or use [`super::GpuOcioResources`] under the `gpu` feature, which builds
    ///   bind groups directly) reports a non-empty `@group(1)`/`@group(2)`, bind those groups exactly
    ///   as declared — this prelude text is the ONLY place that decides which of the three storage
    ///   buffers and how many LUT textures exist, so read the contract rather than guessing;
    /// - start its own bindings at [`super::OCIO_HOST_GROUP_START`] (group 3) or later, never at
    ///   group 1 or 2.
    ///
    /// See `tests/gpu_host_api.rs` for a worked example: a host pipeline with its own entry point, a
    /// host uniform at group 3, and OCIO ops that read `@group(1)` uniforms.
    pub fn wgsl_prelude(&self) -> String {
        let (uniform_bindings, uniforms) = self.build_uniforms();
        self.generate_wgsl_prelude(&uniform_bindings, &uniforms)
    }

    /// The D1 host-buffer compute shell: `textureSampleLevel` an `rgba32float` input, run
    /// `ocio_transform`, `textureStore` an `rgba32float` output. Appended by [`Self::generate_wgsl`]
    /// (the public `generate_shader` path) and by `gpu/runtime.rs`'s buffer-path executor. Built
    /// with the same [`ShaderText`] builder as the prelude, not a hand-typed literal, so indentation
    /// can never drift from what the rest of the emitter produces.
    pub(super) fn wgsl_d1_shell() -> String {
        let mut st = ShaderText::new();
        st.line("@group(0) @binding(0) var input_texture: texture_2d<f32>;");
        st.line(
            "@group(0) @binding(1) var output_texture: texture_storage_2d<rgba32float, write>;",
        );
        st.line("@group(0) @binding(2) var tex_sampler: sampler;");
        st.new_line();
        st.line("@compute @workgroup_size(8, 8)");
        st.line("fn main(@builtin(global_invocation_id) global_id: vec3<u32>) {");
        st.indent();
        st.line("let dims = textureDimensions(input_texture);");
        st.line("if (global_id.x >= dims.x || global_id.y >= dims.y) { return; }");
        st.line("let uv = vec2<f32>(f32(global_id.x) + 0.5, f32(global_id.y) + 0.5) / vec2<f32>(f32(dims.x), f32(dims.y));");
        st.line("let color = textureSampleLevel(input_texture, tex_sampler, uv, 0.0);");
        st.line("let result = ocio_transform(color);");
        st.line("textureStore(output_texture, vec2<i32>(global_id.xy), result);");
        st.dedent();
        st.line("}");
        st.into_code()
    }

    /// Generates WGSL compute shader code: the prelude plus the D1 host-buffer shell.
    pub(super) fn generate_wgsl(
        &self,
        code: &mut String,
        uniform_bindings: &[Option<OpUniforms>],
        uniforms: &[GpuUniform],
    ) {
        code.push_str(&self.generate_wgsl_prelude(uniform_bindings, uniforms));
        code.push_str(&Self::wgsl_d1_shell());
    }

    /// Emit the OCIO uniform layout (STRUCT.4-A.unify).
    ///
    /// All data — scalars and arrays alike — flows through `var<storage, read>`
    /// buffers. This unifies the contract: every OCIO datum is a byte offset
    /// into one of three storage buffers. No `var<uniform>` blocks, no
    /// std140 alignment math, no `array<T, N>` inside a uniform block (which
    /// WGSL forbids for scalar T without 16-byte stride).
    ///
    /// Layout:
    /// - `@group(1) @binding(0) var<storage, read> ocio_scalars: array<u32>`
    ///   holds all scalar uniforms tightly packed. Scalars are bit-cast on
    ///   access via the `scalar_*` accessor fns (Float / Int / Bool / Vec3 /
    ///   Vec4 / Mat3 / Mat4 → 1 / 1 / 1 / 3 / 4 / 9 / 16 `u32` slots).
    /// - `@group(1) @binding(1) var<storage, read> ocio_arrays_i: array<i32>`
    ///   concatenates every `ArrayInt` payload (knots offsets etc.).
    /// - `@group(1) @binding(2) var<storage, read> ocio_arrays_f: array<f32>`
    ///   concatenates every `ArrayFloat` payload (knots, coefs).
    ///
    /// Offset constants emitted alongside the buffers:
    /// - `const <NAME>_OFFSET: u32` — start index of a scalar in `ocio_scalars`.
    /// - `const <NAME>_BASE: u32` + `<NAME>_LEN: u32` — start index + length
    ///   of an array in its concat buffer.
    ///
    /// At most 3 binding slots regardless of how many curves / LUTs the
    /// shader references — well under wgpu's 8-storage-per-stage baseline.
    fn emit_uniform_decls_wgsl(&self, st: &mut ShaderText, uniforms: &[GpuUniform]) {
        if uniforms.is_empty() {
            return;
        }

        // Pass 1: assign u32-slot offsets in `ocio_scalars` for every scalar
        // uniform, and (base, len) pairs in `ocio_arrays_{i,f}` for arrays.
        // Tight u32 packing — no alignment padding because `u32` is the
        // natural element of the storage buffer and reads/writes are 4-byte.
        let mut s_offset: u32 = 0;
        let mut i_base: u32 = 0;
        let mut f_base: u32 = 0;
        // Per-scalar (uniform_name, u32_offset, u32_count).
        let mut scalar_offsets: Vec<(String, u32, u32)> = Vec::new();
        // Per-array (uniform_name, "i" | "f", base, len).
        let mut array_offsets: Vec<(String, &'static str, u32, u32)> = Vec::new();
        for u in uniforms {
            match u.uniform_type {
                GpuUniformType::Float | GpuUniformType::Bool | GpuUniformType::Int => {
                    scalar_offsets.push((u.name.clone(), s_offset, 1));
                    s_offset += 1;
                }
                GpuUniformType::Vec3 => {
                    scalar_offsets.push((u.name.clone(), s_offset, 3));
                    s_offset += 3;
                }
                GpuUniformType::Vec4 => {
                    scalar_offsets.push((u.name.clone(), s_offset, 4));
                    s_offset += 4;
                }
                GpuUniformType::Mat3 => {
                    scalar_offsets.push((u.name.clone(), s_offset, 9));
                    s_offset += 9;
                }
                GpuUniformType::Mat4 => {
                    scalar_offsets.push((u.name.clone(), s_offset, 16));
                    s_offset += 16;
                }
                GpuUniformType::ArrayInt => {
                    let len = u.max_len.unwrap_or(64) as u32;
                    array_offsets.push((u.name.clone(), "i", i_base, len));
                    i_base += len;
                }
                GpuUniformType::ArrayFloat => {
                    let len = u.max_len.unwrap_or(64) as u32;
                    array_offsets.push((u.name.clone(), "f", f_base, len));
                    f_base += len;
                }
            }
        }

        // Storage buffers — only emit those with content. Empty `array<T>`
        // decls would be invalid WGSL, and unused bindings would force the
        // runtime to bind dummy buffers.
        //
        // The group index comes from `super::OCIO_UNIFORM_GROUP` (contract.rs), NOT a literal `1`
        // here — that const is the published host-API contract, and `GpuShaderCode::
        // binding_contract()` derives its own group numbers from the SAME presence checks
        // (`s_offset > 0` etc.) this function uses. Two literals that happen to agree today is
        // exactly the drift the host API (task item 2) exists to rule out.
        let ug = super::OCIO_UNIFORM_GROUP;
        if s_offset > 0 {
            st.linef(format!(
                "@group({ug}) @binding(0) var<storage, read> ocio_scalars: array<u32>;"
            ));
        }
        if i_base > 0 {
            st.linef(format!(
                "@group({ug}) @binding(1) var<storage, read> ocio_arrays_i: array<i32>;"
            ));
        }
        if f_base > 0 {
            st.linef(format!(
                "@group({ug}) @binding(2) var<storage, read> ocio_arrays_f: array<f32>;"
            ));
        }
        if s_offset > 0 || i_base > 0 || f_base > 0 {
            st.new_line();
        }

        // Accessor fns for scalar reads. Each is `inline`-eligible by naga's
        // function call optimizer (they're all single-expression returns), so
        // there's no perf cost vs hand-rolled bitcasts.
        if s_offset > 0 {
            st.line("fn scalar_f32(o: u32) -> f32 {");
            st.indent();
            st.line("return bitcast<f32>(ocio_scalars[o]);");
            st.dedent();
            st.line("}");
            st.new_line();

            st.line("fn scalar_i32(o: u32) -> i32 {");
            st.indent();
            st.line("return bitcast<i32>(ocio_scalars[o]);");
            st.dedent();
            st.line("}");
            st.new_line();

            st.line("fn scalar_u32(o: u32) -> u32 {");
            st.indent();
            st.line("return ocio_scalars[o];");
            st.dedent();
            st.line("}");
            st.new_line();

            st.line("fn scalar_vec3(o: u32) -> vec3<f32> {");
            st.indent();
            st.line(
                "return vec3<f32>(bitcast<f32>(ocio_scalars[o]), \
                 bitcast<f32>(ocio_scalars[o + 1u]), \
                 bitcast<f32>(ocio_scalars[o + 2u]));",
            );
            st.dedent();
            st.line("}");
            st.new_line();

            st.line("fn scalar_vec4(o: u32) -> vec4<f32> {");
            st.indent();
            st.line(
                "return vec4<f32>(bitcast<f32>(ocio_scalars[o]), \
                 bitcast<f32>(ocio_scalars[o + 1u]), \
                 bitcast<f32>(ocio_scalars[o + 2u]), \
                 bitcast<f32>(ocio_scalars[o + 3u]));",
            );
            st.dedent();
            st.line("}");
            st.new_line();

            // Column-major: WGSL `mat3x3<f32>` is column-major; runtime packs
            // 9 consecutive f32s as col0.x col0.y col0.z col1.x ... col2.z.
            st.line("fn scalar_mat3(o: u32) -> mat3x3<f32> {");
            st.indent();
            st.line(
                "return mat3x3<f32>(scalar_vec3(o), scalar_vec3(o + 3u), scalar_vec3(o + 6u));",
            );
            st.dedent();
            st.line("}");
            st.new_line();

            st.line("fn scalar_mat4(o: u32) -> mat4x4<f32> {");
            st.indent();
            st.line(
                "return mat4x4<f32>(scalar_vec4(o), scalar_vec4(o + 4u), \
                 scalar_vec4(o + 8u), scalar_vec4(o + 12u));",
            );
            st.dedent();
            st.line("}");
            st.new_line();
        }

        // Per-scalar `<NAME>_OFFSET` constants.
        for (name, offset, _count) in &scalar_offsets {
            let upper = name.to_uppercase();
            st.linef(format!("const {upper}_OFFSET: u32 = {offset}u;"));
        }
        if !scalar_offsets.is_empty() {
            st.new_line();
        }

        // Per-array `<NAME>_BASE/_LEN` constants.
        for (name, kind, base, len) in &array_offsets {
            let upper = name.to_uppercase();
            st.linef(format!("const {upper}_BASE: u32 = {base}u;"));
            st.linef(format!("const {upper}_LEN: u32 = {len}u;"));
            let _ = kind;
        }
        if !array_offsets.is_empty() {
            st.new_line();
        }
    }

    fn emit_texture_bindings_wgsl(&self, st: &mut ShaderText) {
        // `super::OCIO_TEXTURE_GROUP`, not a literal `2` — see the matching note on
        // `emit_uniform_decls_wgsl`'s `ug`; `GpuShaderCode::binding_contract()` derives the same
        // `(idx+1)*2`/`+1` binding numbers from this same `self.textures` list.
        let tg = super::OCIO_TEXTURE_GROUP;
        for (idx, tex) in self.textures.iter().enumerate() {
            let tex_type = match tex.texture_type {
                GpuTextureType::Texture1D => "texture_1d<f32>",
                GpuTextureType::Texture2D => "texture_2d<f32>",
                GpuTextureType::Texture3D => "texture_3d<f32>",
            };
            // Keep this aligned with batch_texture_descriptors() and consumer
            // code that uses descriptor.binding_index * 2 / +1 for sampler.
            let binding_base = (idx + 1) * 2;
            st.linef(format!(
                "@group({tg}) @binding({binding_base}) var {}: {tex_type};",
                tex.name
            ));
            st.linef(format!(
                "@group({tg}) @binding({}) var {}_sampler: sampler;",
                binding_base + 1,
                tex.name
            ));
        }
        if !self.textures.is_empty() {
            st.new_line();
        }
    }
}
